package fizeau

import (
	"context"
	"os"
	"path/filepath"
	"strings"

	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modelsnapshot"
)

func assembleModelSnapshotFromServiceConfig(ctx context.Context, sc ServiceConfig, cat *modelcatalog.Catalog, cacheRoot string) (modelsnapshot.ModelSnapshot, error) {
	return assembleModelSnapshotFromServiceConfigWithOptions(ctx, sc, cat, cacheRoot, modelsnapshot.AssembleOptions{Refresh: modelsnapshot.RefreshBackground})
}

func assembleModelSnapshotFromServiceConfigWithOptions(ctx context.Context, sc ServiceConfig, cat *modelcatalog.Catalog, cacheRoot string, opts modelsnapshot.AssembleOptions) (modelsnapshot.ModelSnapshot, error) {
	var cfg *modelsnapshot.Config
	if sc != nil {
		cfg = serviceConfigToModelSnapshotConfig(sc)
	}
	cache := &discoverycache.Cache{Root: cacheRoot}
	return modelsnapshot.AssembleWithOptions(ctx, cfg, cat, cache, opts)
}

func serviceSnapshotCacheRoot() (string, error) {
	if override := strings.TrimSpace(os.Getenv("FIZEAU_CACHE_DIR")); override != "" {
		return override, nil
	}
	cacheDir, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(cacheDir, "fizeau"), nil
}

func serviceConfigToModelSnapshotConfig(sc ServiceConfig) *modelsnapshot.Config {
	if sc == nil {
		return nil
	}
	cfg := &modelsnapshot.Config{
		Default:   sc.DefaultProviderName(),
		Providers: make(map[string]modelsnapshot.ProviderConfig, len(sc.ProviderNames())),
	}
	for _, name := range sc.ProviderNames() {
		entry, ok := sc.Provider(name)
		if !ok {
			continue
		}
		cfg.Providers[name] = modelSnapshotProviderConfig(entry)
	}
	return cfg
}

func modelSnapshotProviderConfig(entry ServiceProviderEntry) modelsnapshot.ProviderConfig {
	out := modelsnapshot.ProviderConfig{
		Type:             entry.Type,
		BaseURL:          entry.BaseURL,
		ServerInstance:   entry.ServerInstance,
		Endpoints:        make([]modelsnapshot.ProviderEndpoint, 0, len(entry.Endpoints)),
		APIKey:           entry.APIKey,
		Headers:          cloneStringMap(entry.Headers),
		Model:            entry.Model,
		Billing:          string(entry.Billing),
		IncludeByDefault: nil,
		ContextWindow:    entry.ContextWindow,
		ConfigError:      entry.ConfigError,
		DailyTokenBudget: entry.DailyTokenBudget,
	}
	if entry.IncludeByDefaultSet {
		v := entry.IncludeByDefault
		out.IncludeByDefault = &v
		out.IncludeByDefaultSet = true
	}
	for _, endpoint := range entry.Endpoints {
		out.Endpoints = append(out.Endpoints, modelsnapshot.ProviderEndpoint{
			Name:           endpoint.Name,
			BaseURL:        endpoint.BaseURL,
			ServerInstance: endpoint.ServerInstance,
		})
	}
	return out
}

func cloneStringMap(src map[string]string) map[string]string {
	if len(src) == 0 {
		return nil
	}
	out := make(map[string]string, len(src))
	for k, v := range src {
		out[k] = v
	}
	return out
}

package modelregistry

import (
	"context"
	"os/exec"
	"sort"
	"time"

	"github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
)

// RefreshMode controls whether Assemble refreshes stale source cache data.
type RefreshMode int

const (
	// RefreshBackground preserves the default stale-while-revalidate behavior:
	// return cached data immediately and refresh stale sources in the background.
	RefreshBackground RefreshMode = iota
	// RefreshNone returns cached data only.
	RefreshNone
	// RefreshForce refreshes sources synchronously before reading them.
	RefreshForce
)

// AssembleOptions controls snapshot assembly behavior.
type AssembleOptions struct {
	Refresh RefreshMode
}

// Assemble builds a ModelSnapshot from configured providers, cache-backed
// discovery, runtime status cache state, and model catalog metadata.
func Assemble(ctx context.Context, cfg *config.Config, cat *modelcatalog.Catalog, cache *discoverycache.Cache) (ModelSnapshot, error) {
	return AssembleWithOptions(ctx, cfg, cat, cache, AssembleOptions{Refresh: RefreshBackground})
}

// AssembleWithOptions builds a ModelSnapshot with explicit cache refresh
// behavior for CLI and routing consumers.
func AssembleWithOptions(ctx context.Context, cfg *config.Config, cat *modelcatalog.Catalog, cache *discoverycache.Cache, opts AssembleOptions) (ModelSnapshot, error) {
	asOf := nowUTC()
	snapshot := ModelSnapshot{
		AsOf:    asOf,
		Sources: map[string]SourceMeta{},
	}
	if cfg == nil {
		return snapshot, nil
	}

	providers := enumerateProviders(cfg)
	names := make([]string, 0, len(providers))
	for name := range providers {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, providerName := range names {
		pcfg := providers[providerName]
		discovered := discoverProvider(ctx, providerName, pcfg, cache, opts)
		for source, meta := range discovered.Sources {
			snapshot.Sources[source] = meta
		}
		includeByDefault := effectiveProviderIncludeByDefault(providerName, pcfg, cat)
		billing := effectiveProviderBilling(providerName, pcfg, cat)
		status := providerStatus(cache, providerName)
		for _, discoveredModel := range discovered.Models {
			model := KnownModel{
				Provider:         providerName,
				ProviderType:     discoveredModel.ProviderType,
				Harness:          discoveredModel.Harness,
				ID:               discoveredModel.ID,
				Configured:       discoveredModel.Configured,
				EndpointName:     discoveredModel.EndpointName,
				EndpointBaseURL:  discoveredModel.EndpointBaseURL,
				ServerInstance:   discoveredModel.ServerInstance,
				Billing:          billing,
				IncludeByDefault: includeByDefault,
				DiscoveredVia:    discoveredModel.Via,
				DiscoveredAt:     discoveredModel.DiscoveredAt,
				Status:           status,
			}
			model = enrichModel(model, includeByDefault, cat)
			model = attachRuntimeSignals(model, cache)
			snapshot.Models = append(snapshot.Models, model)
		}
	}
	sort.Slice(snapshot.Models, func(i, j int) bool {
		if snapshot.Models[i].Provider != snapshot.Models[j].Provider {
			return snapshot.Models[i].Provider < snapshot.Models[j].Provider
		}
		if snapshot.Models[i].ProviderType != snapshot.Models[j].ProviderType {
			return snapshot.Models[i].ProviderType < snapshot.Models[j].ProviderType
		}
		if snapshot.Models[i].Harness != snapshot.Models[j].Harness {
			return snapshot.Models[i].Harness < snapshot.Models[j].Harness
		}
		if snapshot.Models[i].EndpointName != snapshot.Models[j].EndpointName {
			return snapshot.Models[i].EndpointName < snapshot.Models[j].EndpointName
		}
		if snapshot.Models[i].EndpointBaseURL != snapshot.Models[j].EndpointBaseURL {
			return snapshot.Models[i].EndpointBaseURL < snapshot.Models[j].EndpointBaseURL
		}
		if snapshot.Models[i].ServerInstance != snapshot.Models[j].ServerInstance {
			return snapshot.Models[i].ServerInstance < snapshot.Models[j].ServerInstance
		}
		return snapshot.Models[i].ID < snapshot.Models[j].ID
	})
	return snapshot, nil
}

// ActiveSources returns the cache sources that are currently configured and
// should be preserved by cache garbage collection.
func ActiveSources(cfg *config.Config) []discoverycache.Source {
	if cfg == nil {
		return nil
	}
	providers := enumerateProviders(cfg)
	names := make([]string, 0, len(providers))
	for name := range providers {
		names = append(names, name)
	}
	sort.Strings(names)

	sources := make([]discoverycache.Source, 0, len(names)*2)
	for _, providerName := range names {
		pcfg := providers[providerName]
		switch normalizeProviderType(pcfg.Type) {
		case "claude", "codex":
			sources = append(sources, discoverycache.Source{
				Tier:            "discovery",
				Name:            providerName,
				TTL:             discoveryTTLPTY,
				RefreshDeadline: discoveryRefreshDeadlinePTY,
			})
		case "openai", "openrouter", "vidar-ds4", "sindri-llamacpp", "ds4", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
			for _, endpoint := range discoveryEndpoints(providerName, pcfg) {
				sources = append(sources, discoverySource(endpointSourceName(providerName, endpoint.Name, endpoint.BaseURL, endpoint.ServerInstance), discoveryTTLForProvider(pcfg), discoveryRefreshDeadlineHTTP))
			}
			if normalizeProviderType(pcfg.Type) == "ds4" || normalizeProviderType(pcfg.Type) == "vidar-ds4" {
				sources = append(sources, discoverySource(providerName+"-props", discoveryTTLHTTPLocal, discoveryRefreshDeadlineHTTP))
			}
		default:
			if pcfg.Model != "" {
				sources = append(sources, discoverySource(providerName, discoveryTTLHTTPRemote, discoveryRefreshDeadlineHTTP))
			}
		}
		sources = append(sources, discoverycache.Source{
			Tier:            "runtime",
			Name:            providerName,
			TTL:             5 * time.Minute,
			RefreshDeadline: 5 * time.Second,
		})
	}
	return sources
}

func enumerateProviders(cfg *config.Config) map[string]config.ProviderConfig {
	out := make(map[string]config.ProviderConfig, len(cfg.Providers)+2)
	for name, pc := range cfg.Providers {
		out[name] = pc
	}
	addImplicitHarness(out, "claude-subscription", "claude", "claude")
	addImplicitHarness(out, "codex-subscription", "codex", "codex")
	return out
}

func addImplicitHarness(providers map[string]config.ProviderConfig, name, providerType, binary string) {
	if _, exists := providers[name]; exists {
		return
	}
	if _, err := exec.LookPath(binary); err != nil {
		return
	}
	include := true
	providers[name] = config.ProviderConfig{
		Type:             providerType,
		IncludeByDefault: &include,
		Billing:          string(modelcatalog.BillingModelSubscription),
	}
}

package modelregistry

import (
	"strings"

	"github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modeleligibility"
	"github.com/easel/fizeau/internal/runtimesignals"
)

const (
	exclusionCatalogUnknown     = "catalog_unknown"
	exclusionCatalogNotRoutable = "catalog_not_auto_routable"
	exclusionProviderExcluded   = "provider_include_by_default_false"
	exclusionStatusUnavailable  = "status_unavailable"
)

func EnrichModel(model KnownModel, includeByDefault bool, cat *modelcatalog.Catalog) KnownModel {
	parsed := modelcatalog.Parse(model.ID)
	model.Family = parsed.Family
	model.Version = append([]int(nil), parsed.Version...)
	model.Tier = parsed.Tier
	model.PreRelease = parsed.PreRelease

	view := modeleligibility.Resolve(model.ID, includeByDefault, string(model.Status), cat)
	model.Power = view.Power
	model.ExactPinOnly = view.ExactPinOnly
	model.AutoRoutable = view.AutoRoutable
	model.ExclusionReason = view.ExclusionReason
	if cat != nil {
		if entry, ok := cat.LookupModel(model.ID); ok {
			model.CostInputPerM = catalogCostInput(entry)
			model.CostOutputPerM = catalogCostOutput(entry)
			model.ContextWindow = entry.ContextWindow
			model.ReasoningLevels = append([]string(nil), entry.ReasoningLevels...)
			model.QuotaPool = entry.EffectiveQuotaPool()
		}
	}
	return model
}

func enrichModel(model KnownModel, includeByDefault bool, cat *modelcatalog.Catalog) KnownModel {
	return EnrichModel(model, includeByDefault, cat)
}

func attachRuntimeSignals(model KnownModel, cache *discoverycache.Cache) KnownModel {
	if cache == nil {
		return model
	}
	sig, ok := runtimesignals.ReadCached(cache, model.Provider)
	if !ok || sig == nil {
		return model
	}
	model.QuotaRemaining = sig.QuotaRemaining
	model.RecentP50Latency = sig.RecentP50Latency
	return model
}

func effectiveProviderIncludeByDefault(providerName string, pc config.ProviderConfig, cat *modelcatalog.Catalog) bool {
	if pc.IncludeByDefault != nil {
		return *pc.IncludeByDefault
	}
	if cat != nil {
		name := strings.ToLower(strings.TrimSpace(providerName))
		providerType := strings.ToLower(strings.TrimSpace(pc.Type))
		for _, provider := range cat.Providers() {
			catalogName := strings.ToLower(strings.TrimSpace(provider.Name))
			catalogType := strings.ToLower(strings.TrimSpace(provider.Type))
			if name != "" && catalogName == name {
				return provider.IncludeByDefault
			}
			if providerType != "" && (catalogType == providerType || catalogName == providerType) {
				return provider.IncludeByDefault
			}
		}
	}
	switch modelcatalog.BillingModel(strings.TrimSpace(pc.Billing)) {
	case modelcatalog.BillingModelFixed, modelcatalog.BillingModelSubscription:
		return true
	case modelcatalog.BillingModelPerToken:
		return false
	}
	if billing := modelcatalog.BillingForProviderSystem(pc.Type); billing != modelcatalog.BillingModelUnknown {
		return billing == modelcatalog.BillingModelFixed || billing == modelcatalog.BillingModelSubscription
	}
	billing := modelcatalog.BillingForHarness(pc.Type)
	return billing == modelcatalog.BillingModelFixed || billing == modelcatalog.BillingModelSubscription
}

func effectiveProviderBilling(providerName string, pc config.ProviderConfig, cat *modelcatalog.Catalog) modelcatalog.BillingModel {
	if billing := modelcatalog.BillingModel(strings.TrimSpace(pc.Billing)); billing != modelcatalog.BillingModelUnknown {
		return billing
	}
	if cat != nil {
		name := strings.ToLower(strings.TrimSpace(providerName))
		providerType := strings.ToLower(strings.TrimSpace(pc.Type))
		for _, provider := range cat.Providers() {
			catalogName := strings.ToLower(strings.TrimSpace(provider.Name))
			catalogType := strings.ToLower(strings.TrimSpace(provider.Type))
			if name != "" && catalogName == name {
				return provider.Billing
			}
			if providerType != "" && (catalogType == providerType || catalogName == providerType) {
				return provider.Billing
			}
		}
	}
	if billing := modelcatalog.BillingForProviderSystem(pc.Type); billing != modelcatalog.BillingModelUnknown {
		return billing
	}
	return modelcatalog.BillingForHarness(pc.Type)
}

func providerStatus(cache *discoverycache.Cache, providerName string) ModelStatus {
	if cache == nil {
		return StatusAvailable
	}
	sig, ok := runtimesignals.ReadCached(cache, providerName)
	if !ok || sig == nil {
		return StatusAvailable
	}
	switch sig.Status {
	case runtimesignals.StatusAvailable, runtimesignals.StatusDegraded:
		return StatusAvailable
	case runtimesignals.StatusExhausted:
		return StatusRateLimited
	case runtimesignals.StatusUnknown:
		return StatusUnknown
	default:
		return StatusUnknown
	}
}

func catalogCostInput(entry modelcatalog.ModelEntry) float64 {
	if entry.CostInputPerM != 0 {
		return entry.CostInputPerM
	}
	return entry.CostInputPerMTok
}

func catalogCostOutput(entry modelcatalog.ModelEntry) float64 {
	if entry.CostOutputPerM != 0 {
		return entry.CostOutputPerM
	}
	return entry.CostOutputPerMTok
}

package agentcli

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"

	agentConfig "github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modelregistry"
	"github.com/easel/fizeau/internal/runtimesignals"
)

type modelsCommandOptions struct {
	JSON         bool
	Provider     string
	PowerMin     int
	PowerMax     int
	IncludeNoise bool
	Refresh      modelregistry.RefreshMode
	Ref          string
}

type modelDetail struct {
	CanonicalID       string                   `json:"canonical_id"`
	KnownModel        modelregistry.KnownModel `json:"known_model"`
	RawDiscoveryData  json.RawMessage          `json:"raw_discovery_data,omitempty"`
	CatalogEntry      *modelcatalog.ModelEntry `json:"catalog_entry,omitempty"`
	RuntimeSignal     *runtimesignals.Signal   `json:"runtime_signal,omitempty"`
	AutoRoutable      autoRoutableComposition  `json:"auto_routable"`
	SourceMeta        modelregistry.SourceMeta `json:"source_meta"`
	SnapshotGenerated time.Time                `json:"snapshot_generated_at"`
}

type autoRoutableComposition struct {
	AutoRoutable bool   `json:"auto_routable"`
	BlockedBy    string `json:"blocked_by,omitempty"`
	Provider     bool   `json:"provider"`
	Catalog      bool   `json:"catalog"`
	Status       bool   `json:"status"`
}

func cmdModels(workDir string, args []string) int {
	opts, err := parseModelsArgs(args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	snapshot, cfg, cat, cache, err := loadModelSnapshot(workDir, opts.Refresh)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	if opts.Ref != "" {
		return cmdModelsDetail(snapshot, cfg, cat, cache, opts)
	}
	return cmdModelsList(snapshot, opts)
}

func parseModelsArgs(args []string) (modelsCommandOptions, error) {
	opts := modelsCommandOptions{Refresh: modelregistry.RefreshBackground}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--json":
			opts.JSON = true
		case arg == "--refresh":
			opts.Refresh = modelregistry.RefreshForce
		case arg == "--no-refresh":
			if opts.Refresh == modelregistry.RefreshForce {
				return opts, fmt.Errorf("--refresh and --no-refresh cannot be combined")
			}
			opts.Refresh = modelregistry.RefreshNone
		case arg == "--include-noise":
			opts.IncludeNoise = true
		case arg == "--provider":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--provider requires a value")
			}
			opts.Provider = args[i]
		case strings.HasPrefix(arg, "--provider="):
			opts.Provider = strings.TrimPrefix(arg, "--provider=")
		case arg == "--power-min":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--power-min requires a value")
			}
			value, err := strconv.Atoi(args[i])
			if err != nil {
				return opts, fmt.Errorf("--power-min: %w", err)
			}
			opts.PowerMin = value
		case strings.HasPrefix(arg, "--power-min="):
			value, err := strconv.Atoi(strings.TrimPrefix(arg, "--power-min="))
			if err != nil {
				return opts, fmt.Errorf("--power-min: %w", err)
			}
			opts.PowerMin = value
		case arg == "--power-max":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--power-max requires a value")
			}
			value, err := strconv.Atoi(args[i])
			if err != nil {
				return opts, fmt.Errorf("--power-max: %w", err)
			}
			opts.PowerMax = value
		case strings.HasPrefix(arg, "--power-max="):
			value, err := strconv.Atoi(strings.TrimPrefix(arg, "--power-max="))
			if err != nil {
				return opts, fmt.Errorf("--power-max: %w", err)
			}
			opts.PowerMax = value
		case strings.HasPrefix(arg, "-"):
			return opts, fmt.Errorf("unknown models flag %s", arg)
		default:
			if opts.Ref != "" {
				return opts, fmt.Errorf("models accepts at most one ref")
			}
			opts.Ref = arg
		}
	}
	return opts, nil
}

func loadModelSnapshot(workDir string, refresh modelregistry.RefreshMode) (modelregistry.ModelSnapshot, *agentConfig.Config, *modelcatalog.Catalog, *discoverycache.Cache, error) {
	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cat, err := cfg.LoadModelCatalog()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	root, err := modelCacheRoot()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cache := &discoverycache.Cache{Root: root}
	snapshot, err := modelregistry.AssembleWithOptions(context.Background(), cfg, cat, cache, modelregistry.AssembleOptions{Refresh: refresh})
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	return snapshot, cfg, cat, cache, nil
}

func modelCacheRoot() (string, error) {
	if override := strings.TrimSpace(os.Getenv("FIZEAU_CACHE_DIR")); override != "" {
		return override, nil
	}
	cacheDir, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(cacheDir, "fizeau"), nil
}

func cmdModelsList(snapshot modelregistry.ModelSnapshot, opts modelsCommandOptions) int {
	models := filterModelRows(snapshot.Models, opts)
	if opts.JSON {
		out := snapshot
		out.Models = models
		data, err := json.MarshalIndent(out, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", err)
			return 1
		}
		fmt.Println(string(data))
		return 0
	}

	tw := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "PROVIDER\tMODEL\tFAMILY\tVERSION\tTIER\tPOWER\tCOST/M\tSTATUS\tCATALOG QUOTA\tRUNTIME QUOTA\tAUTO")
	for _, model := range models {
		fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n",
			model.Provider,
			model.ID,
			emptyDash(model.Family),
			formatVersion(model.Version),
			formatTier(model.Tier),
			formatModelPower(model.Power),
			formatModelCost(model.CostInputPerM, model.CostOutputPerM),
			model.Status,
			emptyDash(model.QuotaPool),
			formatRuntimeQuota(model.QuotaRemaining),
			formatAuto(model),
		)
	}
	_ = tw.Flush()
	return 0
}

func filterModelRows(models []modelregistry.KnownModel, opts modelsCommandOptions) []modelregistry.KnownModel {
	filtered := make([]modelregistry.KnownModel, 0, len(models))
	for _, model := range models {
		if opts.Provider != "" && model.Provider != opts.Provider {
			continue
		}
		if opts.PowerMin > 0 && model.Power < opts.PowerMin {
			continue
		}
		if opts.PowerMax > 0 && model.Power > opts.PowerMax {
			continue
		}
		filtered = append(filtered, model)
	}
	if !opts.IncludeNoise {
		filtered = suppressModelNoise(filtered)
	}
	sort.SliceStable(filtered, func(i, j int) bool {
		if filtered[i].Provider != filtered[j].Provider {
			return filtered[i].Provider < filtered[j].Provider
		}
		if filtered[i].Family != filtered[j].Family {
			return filtered[i].Family < filtered[j].Family
		}
		if cmp := compareVersions(filtered[i].Version, filtered[j].Version); cmp != 0 {
			return cmp > 0
		}
		return filtered[i].ID < filtered[j].ID
	})
	return filtered
}

func suppressModelNoise(models []modelregistry.KnownModel) []modelregistry.KnownModel {
	type groupKey struct {
		provider string
		family   string
		tier     modelcatalog.Tier
	}
	versionsByGroup := map[groupKey]map[string][]int{}
	for _, model := range models {
		if model.Power < 3 {
			continue
		}
		if model.Tier == modelcatalog.TierUnknown && model.Power == 0 {
			continue
		}
		key := groupKey{provider: model.Provider, family: model.Family, tier: model.Tier}
		if key.family == "" {
			continue
		}
		if versionsByGroup[key] == nil {
			versionsByGroup[key] = map[string][]int{}
		}
		versionsByGroup[key][formatVersion(model.Version)] = model.Version
	}

package modelregistry

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/runtimesignals"
)

func TestAssembleFixtureIncludesDiscoveredProviderModels(t *testing.T) {
	t.Setenv("PATH", "")
	cache := &discoverycache.Cache{Root: t.TempDir()}
