		if ids[i] != want[i] {
			t.Fatalf("ids = %#v, want %#v", ids, want)
		}
	}
	if !gotCapturedAt.Equal(capturedAt) {
		t.Fatalf("capturedAt = %v, want %v", gotCapturedAt, capturedAt)
	}
}

