func TestEnrichSnapshotPopulatesCatalogMetadataAndLeavesUnknownZero(t *testing.T) {
	cat := loadTestCatalog(t)

	enriched := EnrichModel(KnownModel{
		Provider: "openrouter",
		ID:       "gpt-5.5",
		Status:   StatusAvailable,
	}, true, cat)
	if enriched.Power != 10 {
