			includeByDefault: true,
			status:           StatusUnknown,
			wantExclusion:    exclusionStatusUnavailable,
		},
		{
			name:             "unreachable status",
			modelID:          "gpt-5.5",
			includeByDefault: true,
			status:           StatusUnreachable,
			wantExclusion:    exclusionStatusUnavailable,
